/// <summary>
/// The <c>METWorkflowStatusForm_WorkflowWorkItemTable_Extension</c> class manages enabled or disable the user mail address.
/// </summary>
/// Added for CFR4 bulk approval AR invoice.
[ExtensionOf(formDataSourceStr(WorkflowStatus, WorkflowWorkItemTable))]
public final class METWorkflowStatusForm_WorkflowWorkItemTable_Extension
{
}

Method.Source:
/// <summary>
/// Enable or disable the user email address.
/// </summary>
public void init()
{
    next init();

    FormRun             formRun      = this.formRun();
    FormStringControl   control      = formRun.design().controlName(formControlStr(WorkflowStatus, METWorkflowWorkItemTable_UserEmailAddress));
    MenuItemName        menuItemName = formRun.args().callerName();

    boolean visible = (menuItemName == menuItemDisplayStr(CustFreeInvoiceAssignedToMeListPage) ||
                       menuItemName == menuItemDisplayStr(CustFreeInvoice) ||
                       menuItemName == menuItemDisplayStr(CustFreeInvoiceListPage)) ? true : false;

    control.visible(visible);
}
